import type { CodeLanguage } from '@pages/components/code-highlight'
import type { ToolName } from '@pages/orin/ToolMark'

/** A short titled list, such as one group of features. */
export interface ItemGroup {
  title: string
  items: readonly string[]
}

/** How fully a cell delivers what its column asks for: all of it, some of it, none of it. */
export type CellState = 'full' | 'partial' | 'none'

/** A state for each cell after the row header, with what each state means in this table. */
export interface TableStates {
  legend: Readonly<Record<CellState, string>>
  /** One row per table row, one state per cell after the row header. */
  cells: readonly (readonly CellState[])[]
}

export interface TableData {
  caption: string
  columns: readonly string[]
  /** The first cell of each row is its row header. */
  rows: readonly (readonly string[])[]
  /** Marks each cell with a state, so the table can be scanned before it is read. */
  states?: TableStates
}

/** A real measurement: the value, what it is, and how it was taken. */
export interface Figure {
  value: string
  label: string
  method: string
}

/** One bar of a comparison: a label, the measured value as text, and its value on the chart's scale. */
export interface RaceBar {
  label: string
  /** The value as the page prints it, such as "2.96 s". */
  text: string
  /** The same value on the chart's one scale (here, seconds). */
  value: number
  /** The tool the page is about. */
  ours?: boolean
}

/** Timings of the same job on the same machine, drawn to scale. Only values the page already states. */
export interface Race {
  title: string
  /** How it was measured, in the smallest text. */
  method: string
  bars: readonly RaceBar[]
}

/** Real output or usage, shown as code. */
export interface Sample {
  caption: string
  language: CodeLanguage
  code: string
  /** Source lines readers may refer to; terminal output and data views stay unnumbered. */
  lineNumbers?: boolean
}

/** A short, ordered path from input to an observable result. */
export interface ProcessStep {
  label: string
  title: string
  text: string
}

/** One concrete type shape and the result a reader can expect from Caliper. */
export interface TypeBoundary {
  title: string
  code: string
  result: string
  state: 'supported' | 'experimental' | 'limited'
}

/** A titled section of a tool page. Copy is short; the content carries the detail. */
export interface ToolSection<Content> {

export interface ToolSection<Content> {
  title: string
  description?: string
  content: Content
  note?: { label: string; links: readonly { label: string; href: string }[] }
}

/**
 * Everything on a tool page below the hero. Written from the tool's repository; the research notes with sources are
 * in docs/research/tools/. Only `why`, `features`, `limits` and `roadmap` are required: a planned tool has little else to show.
 */
export interface ToolPage {
  /** The hero's single command is enough; skip the repeated install section. */
  installInHeroOnly?: boolean
  /** Two or three short sentences: the problem and the answer. */
  why: readonly string[]
  /** Keep a longer pitch on one reading line instead of splitting it across columns. */
  whyLayout?: 'stack'
  /** Three concrete steps when the workflow is central to understanding the tool. */
  process?: ToolSection<readonly ProcessStep[]>
  /** Output or usage, side by side when there are two. */
  samples?: ToolSection<readonly Sample[]>
  /** A concrete result from the tool, before setup instructions. */
  outcome?: ToolSection<TableData>
  /** What changes during development, with a dated result kept in the main reading path. */
  workflow?: ToolSection<readonly ItemGroup[]> & { evidence?: { text: string; label: string; href: string } }
  features: ToolSection<readonly ItemGroup[]> & { layout?: 'stack' | 'editorial' }
  /** Support matrices: languages, harnesses, ecosystems, targets. */
  support?: readonly ToolSection<TableData>[]
  /** Concrete examples for the edges of a type extractor, separate from ecosystem support. */
  typeBoundaries?: ToolSection<readonly TypeBoundary[]>
  figures?: ToolSection<readonly Figure[]>
  /** The same timings as a chart, when the figures include a like-for-like comparison. */
  race?: Race
  compare?: ToolSection<TableData>
  /** Optional routes to the full evidence behind the page's short comparison. */
  deepDives?: ToolSection<
    readonly { title: string; text: string; href: string; eyebrow: string; preview: string; cue: string }[]
  >
  /** How this tool connects to the rest of the family. Planned links say so. */
  worksWith?: readonly { tool: ToolName; text: string; role?: 'builds-on' | 'with' }[]
  /** The other tools build on this one (Michi): its connections are drawn as a base with tools standing on it. */
  foundation?: boolean
  /** What to know before trying it: limits come before claims. */
  limits: readonly string[]
  roadmap: ToolSection<readonly string[]>
}
