import { sva } from '@pages/orin/css'

// A tool's limits, said before its claims. Each one opens with its first sentence in ink and keeps the rest in the body
// colour, so the list can be skimmed and read. The frame is dashed: this is what is not done yet.
const limits = sva({
  slots: ['root', 'item', 'lead'],
  base: {
    root: {
      display: 'grid',
      gap: 'gap.items',
      padding: 'inset.card',
      listStyle: 'none',
      borderWidth: 'hairline',
      borderStyle: 'dashed',
      borderColor: 'border.control',
      borderRadius: 'card',
      color: 'text.body',
      textStyle: 'body',
    },
    item: {},
    lead: { color: 'text', fontWeight: '600' },
  },
})

const slots = limits()

function split(text: string): { lead: string; rest: string } {
  const match = /^(.+?[.!?])(?:\s+(.*))?$/s.exec(text)
  return { lead: match?.[1] ?? text, rest: match?.[2] ?? '' }
}

/** A tool's limits as a framed list. */
export function LimitsList({ items }: { items: readonly string[] }) {
  return (
    <ul className={slots.root}>
      {items.map((item) => {
        const { lead, rest } = split(item)
        return (
          <li key={item} className={slots.item}>
            <span className={slots.lead}>{lead}</span> {rest}
          </li>
        )
      })}
    </ul>
  )
}

