export function Button({
  label,
  variant = 'primary',
  size = 'md',
  disabled = false,
  count = 3,
  onClick,
  icon,
}: ButtonProps) {
  return (
    <button
      type="button"
      data-variant={variant}
      data-size={size}
      disabled={disabled}
      data-count={count}
      onClick={onClick}
