import Launch from '@carbon/icons-react/es/Launch'
import { Button } from '@pages/orin/Button'
import { Icon } from '@pages/orin/Icon'
import { StageChip } from '@pages/orin/StageChip'
import { ToolHero, type ToolHeroProps } from '@pages/orin/ToolHero'
import type { Tool } from '../../data/tools.ts'

/**
 * The tool's identity, its stage, and how to start: the one install command when there is one (passed in as `install`
 * so the page can hydrate its copy button), a jump to the build steps when there are several, and its public repos.
 */
export function ToolPageHero({
  tool,
  install,
  headingAs = 'h1',
}: {
  tool: Tool
  install?: ToolHeroProps['actions']
  headingAs?: 'h1' | 'p'
}) {
  const steps =
    tool.install.kind === 'commands' && tool.install.commands.length > 1
      ? (tool.install.action ?? 'Build from source')
      : undefined
  const download = tool.install.kind === 'commands' ? tool.install.download : undefined
  const actions =
    install || steps || download || tool.links ? (
      <>
        {install}
        {download && (
          <Button href={download.href} iconRight={<Icon glyph={Launch} size={16} />}>
            {download.label}
          </Button>
        )}
        {steps && <Button href="#install-heading">{steps}</Button>}
        {tool.links?.map((link) => (
          <Button key={link.href} href={link.href} variant="secondary" iconRight={<Icon glyph={Launch} size={16} />}>
            {link.label}
          </Button>
        ))}
      </>
    ) : undefined
  return (
    <ToolHero
      tool={tool.id}
      name={tool.id}
      family={tool.family}
      description={tool.summary}
      stage={<StageChip stage={tool.stage} />}
      actions={actions}
      headingAs={headingAs}
      classes={{ root: 'lx-page' }}
    />
  )
}
