import { mergeSlots, type SlotClasses } from '@pages/foundations/slots'
import type { ComponentPropsWithRef, ReactNode } from 'react'
import { toolHero, type ToolHeroVariant } from '../../styled-system/recipes'
import { FamilyChip } from '../chip/familyChip.tsx'
import { Lattice } from '../lattice/lattice.tsx'
import { ToolMark, type ToolName } from '../mark/toolMark.tsx'

export type ToolHeroProps = Omit<ComponentPropsWithRef<'section'>, 'children' | 'className'> & {
  family: NonNullable<ToolHeroVariant['family']>
  tool: ToolName
  name: string
  description: ReactNode
  mark?: ReactNode
  stage: ReactNode
  actions?: ReactNode
  headingAs?: 'h1' | 'h2' | 'h3' | 'p'
  classes?: SlotClasses<typeof toolHero>
}

/** Full tool page identity with a tinted lattice and caller-owned stage/actions. */
export function ToolHero({
  family,
  tool,
  name,
  description,
  mark,
  stage,
  actions,
  headingAs = 'h1',
  classes,
  ...props
}: ToolHeroProps) {
  const slots = mergeSlots(toolHero({ family }), classes)
  const Heading = headingAs
  return (
    <section
      {...props}
      aria-label={name}
      data-recipe="tool-hero"
      data-family={family}
      data-slot="root"
      className={slots.root}
    >
      <div data-slot="inner" className={slots.inner}>
        <div aria-hidden="true" data-slot="mark" className={slots.mark}>
          <Lattice level="tool" />
          {mark ?? <ToolMark tool={tool} size="fluid" treatment="hero" />}
        </div>
        <div data-slot="content" className={slots.content}>
          <div data-slot="byline" className={slots.byline}>
            <span data-slot="brace" className={slots.brace}>
              {'{'}
            </span>{' '}
            orin dx{' '}
            <span data-slot="brace" className={slots.brace}>
              {'}'}
            </span>
          </div>
          <Heading data-slot="title" className={slots.title}>
            {name}
          </Heading>
          <p data-slot="description" className={slots.description}>
            {description}
          </p>
          <div data-slot="meta" className={slots.meta}>
            <div data-slot="family" className={slots.family}>
              <FamilyChip family={family}>{family}</FamilyChip>
            </div>
            <div data-slot="stage" className={slots.stage}>
              {stage}
            </div>
          </div>
          {actions && (
            <div data-slot="actions" className={slots.actions}>
              {actions}
            </div>
          )}
        </div>
      </div>
    </section>
  )
}
