import { mergeSlots, type SlotClasses } from '@pages/foundations/slots'
import type { ComponentPropsWithRef } from 'react'
import { lattice, type LatticeVariant } from '../../styled-system/recipes'

export type LatticeProps = Omit<ComponentPropsWithRef<'div'>, 'children' | 'className'> &
  LatticeVariant & { classes?: SlotClasses<typeof lattice> }

/** Decorative hexagonal field, centred on its parent (the art slot of a hero or intro), which provides the tint. */
export function Lattice({ full, soft, level, classes, ...props }: LatticeProps) {
  const slots = mergeSlots(lattice({ full, soft, level }), classes)
  return (
    <div
      {...props}
      aria-hidden="true"
      data-recipe="lattice"
      data-full={full || undefined}
      data-soft={soft || undefined}
      data-slot="root"
      className={slots.root}
    />
  )
}
