type CustomProperties = Record<`--${string}`, string>

/** The ribbon's outline as a blurred mask image, in the lattice field's own units. */
function silhouette(path: RibbonPath): string {
  const { spine } = ribbonGeometry(path)
  const line = spine.map((p) => `${p.x} ${p.y}`).join(' L ')
  const svg =
    `<svg xmlns='http://www.w3.org/2000/svg' width='${fieldBox.width}' height='${fieldBox.height}'>` +
    `<defs><filter id='b' x='-30%' y='-30%' width='160%' height='160%'><feGaussianBlur stdDeviation='16'/></filter></defs>` +
    `<g filter='url(#b)'><path d='M ${line}' fill='none' stroke='white' stroke-width='96' stroke-linecap='round' stroke-linejoin='round'/></g></svg>`
  return `url("data:image/svg+xml;utf8,${encodeURIComponent(svg)}")`
}

