const bitSlots = ['bitA', 'bitB', 'bitC', 'bitD'] as const

/** The twisting bundle: wild at one end, pinched through gates, calmer at the other. Static SVG, drawn on the server. */
export function Ribbon({ tone = 'ramp', path = 'hero', classes, ...props }: RibbonProps) {
  const id = useId()
  const slots = mergeSlots(ribbon({ tone }), classes)
  const geometry = ribbonGeometry(path)
