import { Table } from '@pages/orin/Table'
import { css } from '@pages/orin/css'
import type { Meta, StoryObj } from '@storybook/react-vite'

const frame = css({ padding: '6', maxWidth: '[48rem]' })

const meta = {
  title: 'Orin DX/Data/Table',
  component: Table,
  tags: ['autodocs'],
  args: {
    caption: 'Tools',
    columns: ['tool', 'family', 'stage'],
    rows: [
      ['caliper', 'build', 'pre-release'],
      ['lumen', 'measure', 'built, unpublished'],
      ['wisp', 'know', 'early'],
    ],
  },
  argTypes: {
    caption: { control: 'text' },
    hideCaption: { control: 'boolean' },
    groupSize: { control: 'number' },
    columns: { control: false },
    rows: { control: false },
    rowTones: { control: false },
    classes: { control: false },
  },
} satisfies Meta<typeof Table>

export default meta
type Story = StoryObj<typeof meta>

export const Playground: Story = {
  render: (args) => (
    <div className={frame}>
      <Table {...args} />
    </div>
  ),
}

/**
 * One row per tool per subject, with the tool in a column so every heading stays one short word. `rowTones` colours each
 * row by role in the colours the charts use, and `groupSize` closes each pair with a heavier rule.
 */
export const Pairs: Story = {
  ...Playground,
  args: {
    caption: 'Wrong types and time, Caliper and RDT',
    columns: ['library', 'tool', 'wrong', 'time'],
    rows: [
      ['Mantine', 'Caliper', '0', '286 ms'],
      ['Mantine', 'RDT', '9 (0.04%)', '4.7 s'],
      ['Chakra', 'Caliper', '1 (<0.01%)', '903 ms'],
      ['Chakra', 'RDT', '30 (<0.01%)', '59.3 s'],
    ],
    groupSize: 2,
    rowTones: ['focus', 'reference', 'focus', 'reference'],
  },
}

